259	/** A monitor the builder may edit, as stored: its type, its app and its sealed header values,
260	 *  read in the member's workspace. An automatic monitor, or a type not live yet, is refused. */
261	async function storedMonitor(member: Member, monitorId: string): Promise<{ type: string; appId: string; target: string; sealed: Map<string, string> } | Refusal> {
262	  const ws = member.workspace.id;
263	  const [{ data: mon, error: monError }, { data: stored, error: storedError }] = await Promise.all([
264	    db().from("monitors").select("type, app_id, auto, target").eq("id", monitorId).eq("workspace_id", ws).maybeSingle(),
265	    db().from("monitor_secrets").select("name, sealed").eq("monitor_id", monitorId).eq("workspace_id", ws),
266	  ]);
267	  if (monError || storedError) return refused((monError ?? storedError)!, member);
268	  if (!mon) return NOT_FOUND;
269	  if (mon.auto || !isCreatable(mon.type)) return refused({ message: mon.auto ? "auto_monitor" : "type_not_available" }, member);
270	  return { type: mon.type, appId: mon.app_id, target: mon.target, sealed: new Map((stored ?? []).map((s) => [s.name, s.sealed])) };
271	}
272	
273	const isRefusal = (x: object): x is Refusal => "ok" in x;
274	
275	/** A kept secret header goes only to the address it was saved for. Any other address, another
276	 *  path on the same site included, means typing it again, so nobody who can edit a monitor can
277	 *  send a secret someone else typed to an address of their choosing, by saving or by testing:
278	 *  not to their own server, and not to a path of the same site that echoes what it's sent. */
279	function keptHeaderMoved(row: { type: string; target: string; secrets: readonly { name: string; value: string }[] }, storedTarget: string): Refusal | null {
280	  if (row.type !== "http" && row.type !== "supabase") return null;
281	  const address = (url: string) => {
282	    try {
283	      return new URL(url).href;
284	    } catch {
285	      return null;
286	    }
287	  };
288	  const kept = row.secrets.find((s) => !s.value);
289	  if (!kept || (address(row.target) !== null && address(row.target) === address(storedTarget))) return null;
290	  const reason = `Type ${kept.name} again: a kept value is only sent to the address it was saved for.`;
291	  return { ok: false, reason, fieldErrors: { [row.type === "supabase" ? "key" : "headers"]: reason } };
292	}
