294	/** Service saves cannot bypass preflight by posting an action directly or reusing a stale
295	 * browser test. Verification happens after ownership and budget checks, before any write. */
296	async function saveServiceMonitor(member: Member, id: string, row: MonitorRow, editing: boolean, stored = new Map<string, string>()): Promise<Result<{ id: string }>> {
297	  const spent = await spendTest(member);
298	  if (spent) return spent;
299	  let key = row.secrets[0]?.value ?? "";
300	  if (!key) {
301	    try { key = open(stored.get(SERVICE_KEY) ?? "", headerContext(id, SERVICE_KEY)); }
302	    catch { return { ok: false, reason: "Type the key again; its stored value could not be read.", fieldErrors: { key: "Type the key again." } }; }
303	  }
304	  const outcome = await runTest(row, { [SERVICE_KEY]: key }, TEST_DEADLINE_MS);
305	  if (!("service" in outcome) || !outcome.service.saveable) return { ok: false,
306	    reason: outcome.failure?.message ?? "Verify every service check before saving.", fieldErrors: { form: outcome.failure?.message ?? "The configuration could not be verified." } };
307	  const L = member.entitlements.limits;
308	  const { error } = await db().rpc("save_service_monitor", {
309	    p_workspace_id: member.workspace.id, p_id: id, p_app_id: row.appId, p_type: row.type,
310	    p_name: row.name, p_target: row.target, p_config: row.config as never,
311	    p_sealed: seal(key, headerContext(id, SERVICE_KEY)), p_edit: editing,
312	    p_max_monitors: L.monitors, p_max_type: row.type === "stripe" ? L.stripeAccounts : L.supabaseMonitors === "cap" ? L.monitors : L.supabaseMonitors,
313	    p_per_host: L.perHost === "fair use" ? L.monitors : L.perHost,
314	    p_interval_sec: (row.type === "stripe" ? L.stripePollMin : L.httpIntervalMin) * 60,
315	  });
316	  return error ? refused(error, member, { type: row.type }) : { ok: true, id };
317	}
