319	/** What a monitor checks, changed. Its type, app, heartbeat URL and history stay. */
320	export async function updateMonitor(monitorId: string, draft: unknown): Promise<Result> {
321	  const member = await begin();
322	  if (!isMember(member)) return member;
323	  if (!(reach(member, await resolveMonitor(monitorId), "monitors:write"))) return NOT_FOUND;
324	
325	  const ws = member.workspace.id;
326	  const mon = await storedMonitor(member, monitorId);
327	  if (isRefusal(mon)) return mon;
